<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';if(is_file(__DIR__.'/../app/admin_layout.php'))require_once __DIR__.'/../app/admin_layout.php';if(is_file(__DIR__.'/../app/access_control_v1300.php'))require_once __DIR__.'/../app/access_control_v1300.php';require_once __DIR__.'/../app/services_v1380.php';if(!sk1380_admin()){http_response_code(403);exit('Access denied.');}$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{sk1380_csrf_check();$id=(int)$_POST['promotion_id'];$act=(string)$_POST['action'];$q=sk1380_db()->prepare('SELECT * FROM service_promotions_v1380 WHERE tenant_id=? AND id=? AND status="pending" LIMIT 1');$q->execute([sk1380_tid(),$id]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new RuntimeException('Promotion is not pending.');if($act==='approve'){$start=date('Y-m-d H:i:s');$end=date('Y-m-d H:i:s',strtotime('+30 days'));$pdo=sk1380_db();$pdo->beginTransaction();$pdo->prepare('UPDATE service_promotions_v1380 SET status="approved",starts_at=?,ends_at=?,admin_note=?,reviewed_by=?,updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([$start,$end,trim((string)($_POST['admin_note']??''))?:null,sk1380_uid(),sk1380_tid(),$id]);if($r['promotion_type']==='featured_provider')$pdo->prepare('UPDATE service_provider_profiles_v1380 SET featured_until=?,updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([$end,sk1380_tid(),$r['provider_id']]);elseif($r['promotion_type']==='featured_service'&&$r['offering_id'])$pdo->prepare('UPDATE service_offerings_v1380 SET featured_until=?,updated_at=NOW() WHERE tenant_id=? AND id=? AND provider_id=?')->execute([$end,sk1380_tid(),$r['offering_id'],$r['provider_id']]);$pdo->commit();$msg='Payment verified and promotion activated for 30 days.';}elseif($act==='reject'){sk1380_db()->prepare('UPDATE service_promotions_v1380 SET status="rejected",admin_note=?,reviewed_by=?,updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([trim((string)($_POST['admin_note']??''))?:null,sk1380_uid(),sk1380_tid(),$id]);$msg='Promotion rejected.';}}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}}$rows=[];try{$q=sk1380_db()->prepare('SELECT pr.*,p.business_name,p.display_name,so.title service_title FROM service_promotions_v1380 pr JOIN service_provider_profiles_v1380 p ON p.id=pr.provider_id LEFT JOIN service_offerings_v1380 so ON so.id=pr.offering_id WHERE pr.tenant_id=? ORDER BY FIELD(pr.status,"pending","approved","rejected"),pr.id DESC LIMIT 300');$q->execute([sk1380_tid()]);$rows=$q->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){$err=trim($err.' '.$e->getMessage());}sk1380_admin_header('Service Promotions');?><div class="svc-admin"><section class="admin-hero"><div><span>PAID VISIBILITY CONTROL</span><h1>Service Promotions</h1><p>Approve only after verifying the provider's submitted payment/reference. Search priority, provider feature and service feature are time-bounded.</p></div><a href="/admin/services.php">← Dashboard</a></section><?php if($msg):?><div class="notice ok"><?=sk1380_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=sk1380_h($err)?></div><?php endif;?><div class="approval-list"><?php foreach($rows as $r):?><article><div><b><?=sk1380_h($r['business_name']?:$r['display_name'])?></b><p><?=sk1380_h(str_replace('_',' ',strtoupper($r['promotion_type'])))?><?=$r['service_title']?' · '.sk1380_h($r['service_title']):''?></p><small>PKR <?=number_format((float)$r['amount_snapshot'],0)?> · Ref <?=sk1380_h($r['payment_reference'])?><?php if($r['starts_at']):?> · <?=sk1380_h($r['starts_at'])?> → <?=sk1380_h($r['ends_at'])?><?php endif;?></small></div><strong class="state <?=sk1380_h($r['status'])?>"><?=sk1380_h($r['status'])?></strong><?php if($r['status']==='pending'):?><form method="post"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="promotion_id" value="<?=$r['id']?>"><input name="admin_note" placeholder="Verification note"><button name="action" value="approve">Verify & Activate</button><button name="action" value="reject" class="danger">Reject</button></form><?php endif;?></article><?php endforeach;?></div></div><?php sk1380_admin_footer();